import java.util.*;import java.util.zip.*;import java.nio.file.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import org.objectweb.asm.tree.analysis.*;
public class Patch implements Opcodes{
 static int hooks;static final String P="dev/tactical/tacz/";
 static byte[] patch(byte[] b)throws Exception{ClassNode c=new ClassNode();new ClassReader(b).accept(c,0);int before=hooks;for(MethodNode m:c.methods){
  if(c.name.equals(P+"ClientEffects")&&m.name.equals("impact")){InsnList x=new InsnList();x.add(new FieldInsnNode(GETSTATIC,P+"ImpactMarks","replay","Z"));LabelNode original=new LabelNode();x.add(new JumpInsnNode(IFEQ,original));x.add(new InsnNode(RETURN));x.add(original);x.add(new FrameNode(F_SAME,0,null,0,null));m.instructions.insert(x);hooks++;}
  if(c.name.equals(P+"ImpactMarks")&&m.name.equals("configure"))for(AbstractInsnNode a:m.instructions.toArray())if(a instanceof MethodInsnNode mc&&mc.owner.equals(P+"TimedMarks")&&mc.name.equals("configure")){mc.owner=P+"OnceEffects";hooks++;}
 }if(before==hooks)return b;ClassWriter w=new ClassWriter(ClassWriter.COMPUTE_MAXS);c.accept(w);ClassNode v=new ClassNode();new ClassReader(w.toByteArray()).accept(v,0);for(MethodNode m:v.methods)if((m.access&(ACC_ABSTRACT|ACC_NATIVE))==0)new Analyzer<BasicValue>(new BasicVerifier()).analyze(v.name,m);return w.toByteArray();}
 public static void main(String[]a)throws Exception{Map<String,byte[]>entries=new TreeMap<>();try(ZipFile z=new ZipFile(a[0])){for(ZipEntry e:Collections.list(z.entries())){byte[] b=z.getInputStream(e).readAllBytes();entries.put(e.getName(),e.getName().endsWith(".class")?patch(b):b);}}if(hooks!=2)throw new IllegalStateException("hooks "+hooks);try(var paths=Files.walk(Path.of(a[2]))){for(Path p:paths.filter(p->p.toString().endsWith(".class")).toList())entries.put(Path.of(a[2]).relativize(p).toString(),Files.readAllBytes(p));}try(ZipOutputStream z=new ZipOutputStream(Files.newOutputStream(Path.of(a[1])))){for(var e:entries.entrySet()){ZipEntry n=new ZipEntry(e.getKey());n.setTime(0);z.putNextEntry(n);z.write(e.getValue());z.closeEntry();}}System.out.println("Two one-shot visual hooks verified");}
}
